@page "/board"
@using sv_4b05102991fd4df687c94b045437d1d2.Components.Pages.BoardComponents
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h2>Project Board</h2>

@if (loading)
{
    <p class="loading">Loading tasks...</p>
}
else if (errorMessage is not null)
{
    <p class="error">@errorMessage</p>
}
else
{
    <BoardStats Tasks="allTasks" />
    <BoardSearchBar SearchTerm="@searchTerm" SearchTermChanged="OnSearchChanged" />

    <div class="kanban-board">
        <KanbanColumn ColumnName="To Do"
                      Tasks="@GetFilteredTasks(StatusToDo)"
                      ShowMoveLeft="false"
                      ShowMoveRight="true"
                      OnMoveRight="@((id) => MoveTask(id, StatusInProgress))"
                      OnAddTask="@((data) => AddTask(data, StatusToDo))" />

        <KanbanColumn ColumnName="In Progress"
                      Tasks="@GetFilteredTasks(StatusInProgress)"
                      ShowMoveLeft="true"
                      ShowMoveRight="true"
                      OnMoveLeft="@((id) => MoveTask(id, StatusToDo))"
                      OnMoveRight="@((id) => MoveTask(id, StatusDone))"
                      OnAddTask="@((data) => AddTask(data, StatusInProgress))" />

        <KanbanColumn ColumnName="Done"
                      Tasks="@GetFilteredTasks(StatusDone)"
                      ShowMoveLeft="true"
                      ShowMoveRight="false"
                      OnMoveLeft="@((id) => MoveTask(id, StatusInProgress))"
                      OnAddTask="@((data) => AddTask(data, StatusDone))" />
    </div>
}

